71	    await expect(draft.billingAddressSection).toContainText(address.streetAddress1);
72	  });
73	
74	  await test.step("set a shipping method", () => draft.setFirstShippingMethod());
75	
76	  await test.step("finalize into an unfulfilled order", async () => {
77	    await draft.finalize();
78	    await expect(draft.statusInfo).toHaveText("Unfulfilled");
79	    await expect(draft.customerSection).toContainText(email);
80	  });
81	});
