async (page) => {
  const item = page.getByRole("menuitem", { name: "Cancel order" });
  const html = await page.getByRole("menu").evaluate(e => e.outerHTML.slice(0, 800));
  await item.click();
  const dlg = page.getByRole("dialog");
  await dlg.waitFor();
  const btns = await dlg.locator("button").evaluateAll(bs => bs.map(b => ({ t: b.innerText, id: b.getAttribute("data-test-id") })));
  return { html, text: await dlg.innerText(), btns, heading: await dlg.getByRole("heading").allInnerTexts().catch(()=>null) };
}

async (page) => {
  const draftUrl = page.url().split("?")[0];
  const hasTestId = await page.locator('[data-test-id="cancel-order"]').count();
  await page.getByRole("dialog").getByRole("button", { name: "Delete" }).click();
  await page.waitForURL(u => !u.pathname.includes("/drafts/T"));
  await page.waitForTimeout(1500);
  const after = { url: page.url(), title: await page.title(), toasts: await page.getByRole("region", { name: /Notifications/ }).innerText() };
  const listText = (await page.locator("main").first().innerText()).slice(0, 600);
  await page.goto(draftUrl);
  await page.waitForTimeout(2500);
  const nf = { url: page.url(), title: await page.title(), text: (await page.locator("main").first().innerText()).slice(0, 800) };
  return { draftUrl, hasTestId, after, listText, nf };
}

